/** Archived issues whose `archivedAt` is at or before `cutoff`, across all projects. */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        sql`${issues.archivedAt} <= ${cutoff}`,
      ),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

export interface PurgeIssuesResult {
  readonly commentIds: readonly string[];
  readonly storageMb: number;
}

/**
 * Permanently deletes issues with their label links, comments and attachments,
 * keeping the project's number high-water mark so numbers are never reused.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeIssuesResult> {
  if (issueIds.length === 0) return { commentIds: [], storageMb: 0 };
  const ids = [...issueIds];

  return getDb().transaction((tx) => {
    const marks = tx
      .select({
        projectId: issues.projectId,
        value: sql<number>`max(${issues.number})`,
      })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .groupBy(issues.projectId)
      .all();
    for (const mark of marks) {
      tx.insert(issueNumberMarks)
        .values({ projectId: mark.projectId, maxNumber: mark.value })
        .onConflictDoUpdate({
          target: issueNumberMarks.projectId,
          set: {
            maxNumber: sql`max(${issueNumberMarks.maxNumber}, ${mark.value})`,
          },
        })
        .run();
    }

    const commentIds = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .all()
      .map((row) => row.id);

    const sizes = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all();
    const storageMb = sizes.reduce(
      (sum, row) => sum + Math.ceil(row.sizeBytes / (1024 * 1024)),
      0,
    );

    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .run();
    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    return { commentIds, storageMb };
  });
}
